<section class="user-area"><div class="container user-layout"><?php require view_path('components/user/sidebar.php'); ?><div class="user-main"><header class="user-page-head"><div><span class="eyebrow">Account Settings</span><h1>پروفایل من</h1><p>اطلاعات فردی و حرفه‌ای حساب خود را مدیریت کنید.</p></div></header><div class="profile-grid"><section class="user-panel profile-form"><header><div><h2>اطلاعات حساب</h2><p>ایمیل حساب بعد از ثبت‌نام قابل تغییر نیست.</p></div></header><?php if ($success): ?><div class="alert alert--success" role="status"><strong>پروفایل شما به‌روزرسانی شد.</strong></div><?php endif; ?><?php if ($errors): ?><div class="alert alert--danger" role="alert"><strong>لطفاً اطلاعات فرم را بررسی کنید.</strong></div><?php endif; ?><form class="stack" method="post" action="/profile"><?= csrf_field() ?><label class="form-group"><span class="form-label">نام و نام خانوادگی</span><input class="form-control" name="name" value="<?= e($old['name'] ?? $user['name']) ?>" required><?php if (isset($errors['name'])): ?><span class="form-error"><?= e($errors['name'][0]) ?></span><?php endif; ?></label><label class="form-group"><span class="form-label">ایمیل</span><input class="form-control ltr" value="<?= e($user['email']) ?>" disabled><span class="form-hint">برای تغییر ایمیل با پشتیبانی تماس بگیرید.</span></label><div class="grid grid--2"><label class="form-group"><span class="form-label">شماره تماس</span><input class="form-control ltr" name="phone" value="<?= e($old['phone'] ?? $user['phone']) ?>"></label><label class="form-group"><span class="form-label">نقش حرفه‌ای</span><select class="form-select" name="role"><option value="">انتخاب کنید</option><?php foreach (['دانشجو','روان‌شناس / درمانگر','پژوهشگر','مدرس / منتور','مدیر / متخصص منابع انسانی','سایر'] as $role): ?><option <?= ($old['role'] ?? $user['role']) === $role ? 'selected' : '' ?>><?= e($role) ?></option><?php endforeach; ?></select></label></div><label class="form-group"><span class="form-label">درباره من</span><textarea class="form-textarea" name="bio" maxlength="500" placeholder="کمی درباره مسیر حرفه‌ای و علایق خود بنویسید."><?= e($old['bio'] ?? $user['bio']) ?></textarea><?php if (isset($errors['bio'])): ?><span class="form-error"><?= e($errors['bio'][0]) ?></span><?php endif; ?></label><button class="btn btn--primary" type="submit">ذخیره تغییرات</button></form></section><aside class="profile-summary user-panel"><div class="profile-avatar"><?= e(mb_substr($user['name'], 0, 1)) ?></div><h2><?= e($user['name']) ?></h2><p><?= e($user['role'] ?: 'نقش حرفه‌ای ثبت نشده') ?></p><dl><div><dt>عضویت از</dt><dd><?= e(substr($user['created_at'], 0, 10)) ?></dd></div><div><dt>وضعیت حساب</dt><dd><span class="badge badge--success">فعال</span></dd></div></dl><small class="form-hint">برای تغییر رمز، ابتدا از حساب خارج شوید و از بازیابی رمز استفاده کنید.</small></aside></div></div></div></section>
